// ora-fc-fin — generated from src/ora-fc-fin-*.js by tools/merge.js. Edit the src files, then run: node tools/merge.js
// Oracle Functional Consultant (2–3 yrs) — Finance. Format: [module, question, answer, 'B' basic | 'D' in-depth]
QB["ora-fc-fin"] = (QB["ora-fc-fin"] || []).concat([
["Fusion Basics", "What is the difference between Oracle E-Business Suite and Oracle Fusion Cloud ERP?", "**Why they ask:** a basic question, but it shows whether you understand how the work changes.\n\n**Answer:**\n\"EBS is on-premise or hosted. The customer owns the database, applies patches, and can customize code directly. It has a Forms UI, concurrent programs and responsibilities. Fusion Cloud ERP is SaaS: Oracle hosts it and upgrades it every quarter. There's no direct database access, so we extend through configuration, Visual Builder, OIC, BI Publisher and REST APIs. It has a browser UI, scheduled processes and role-based security. For a consultant, setups are done through Functional Setup Manager tasks, every quarterly update needs regression testing, and reporting uses OTBI, BI Publisher and Financial Reporting or Smart View.\"\n\nTip: If you've worked on both, give one task you did in each. It proves the experience.", "B", null, null, {"t":1,"f":["What does the quarterly update cycle mean for a consultant?","Every quarter Oracle pushes an update, so we read the release notes, test the key flows — journal entry, invoice-to-pay, receipt application — in a non-production pod about two weeks before production, and switch on new features deliberately. Regression testing becomes a routine part of support, ideally automated, not a one-off project."]}],
["Fusion Basics", "What is Functional Setup Manager and how do you use it?", "**Why they ask:** FSM is how every Fusion setup is done.\n\n**Answer:**\n\"FSM is the Fusion tool for all application setup. Offerings, like Financials, contain functional areas, like Payables, which contain setup tasks, like Manage Payables Options. You opt in to the offerings and features you need and work through the task list. Implementation projects group tasks so you can assign them and track status. Configuration packages export setups from one environment and import them into another, like test to production. And scope values let you set up a task for a specific BU or ledger.\"\n\nTip: Mention configuration packages. It shows you know how setups move between environments.", "B", null, null, {"f":["What's the difference between an offering and a functional area?","An offering is a broad product like Financials; functional areas are parts of it, like Payables or Assets. You opt in to both, and only opted-in areas show their setup tasks."]}],
["General Ledger", "What are the \"4 Cs\" of a ledger in Oracle?", "**Why they ask:** a basic question that every Oracle Financials consultant should answer quickly.\n\n**Answer:**\n\"A ledger is defined by four things: the chart of accounts, which is the account structure; the calendar, which defines the periods, like monthly or 4-4-5; the currency; and the accounting method, which is the Subledger Accounting method that tells subledgers how to create journals. Two legal entities can share a primary ledger only if all four are the same. If any one differs, they need separate ledgers.\"\n\nTip: Add the rule about sharing a ledger. It turns a definition into a design point.", "B", null, null, {"t":1,"f":["Which of the four Cs can two ledgers in a ledger set differ on?","Currency. Ledgers in a ledger set must share the same chart of accounts and accounting calendar, but they can have different currencies — for example a US ledger in USD and a UK ledger in GBP in one set, so you can open and close periods and run reports across both at once."]}],
["General Ledger", "What is a balancing segment and why is it important?", "**Why they ask:** balancing segments drive entity reporting and intercompany.\n\n**Answer:**\n\"The balancing segment is the chart of accounts segment, usually company, for which Oracle makes sure debits equal credits on every journal. If a journal crosses two balancing values, say company 101 and 102, Oracle adds intercompany balancing lines automatically using the intercompany rules. Balancing values are usually assigned to legal entities, so you can produce a balance sheet for each entity. Fusion supports up to three balancing segments, for example company and cost center, if the business needs a balance sheet at that level too.\"\n\nTip: Mention the three balancing segments. It's a Fusion detail that shows current knowledge.", "B", null, null, {"t":1,"f":["What happens if you have two companies but only one balancing segment value?","You can't produce a balanced balance sheet for each company, because Oracle only forces debits and credits to balance by balancing segment value. Each legal entity needs its own balancing values; otherwise intercompany entries net out inside one value and you lose the separate trial balance per company."]}],
["General Ledger", "Walk me through the life of a manual journal entry in Fusion GL.", "**Why they ask:** a basic GL question that shows whether you know the controls along the way.\n\n**Answer:**\n\"It starts with creating the journal, either on the Create Journal page or by uploading the ADFdi spreadsheet, with batch, journal, ledger, period, category and lines. As lines are entered, cross-validation rules check every account combination and reject invalid ones. If journal approval is on for that source, it routes through the BPM rules, usually by amount. Once approved, it's posted, either by hand or by AutoPost, and posting updates the balances and the cube. If it's an accrual, it's set to reverse automatically in the next period.\"\n\nTip: Mention the spreadsheet upload. Most finance teams enter journals that way, and it shows you've worked with them.", "B", null, null, {"t":1,"f":["What stops a user from posting their own large journal?","Journal approval rules — for example any journal over $50,000, or any journal touching cash or revenue accounts, routes to the controller before posting. Add segregation of duties so the preparer role can't approve or post its own entries, and review the posted-journal audit report at month end."]}],
["General Ledger", "What are cross-validation rules?", "**Why they ask:** a basic COA control that every GL consultant sets up.\n\n**Answer:**\n\"Cross-validation rules stop invalid combinations of segment values from being created. For example, 'balance sheet accounts, 1000 to 3999, must use cost center 000'. Each rule has a condition filter, which says when it applies, a validation filter, which says what's allowed, and an error message the user sees. One thing to know: they only stop new combinations. Combinations that already exist have to be disabled separately. So I set them up before transactions start, and test them with real account strings.\"\n\nTip: Make the point that they only block new combinations. It's the follow-up question.", "B", null, null, {"f":["What's the difference between cross-validation rules and segment value security?","Cross-validation stops invalid combinations from being created for anyone. Segment value security restricts which values specific users can use."]}],
["General Ledger", "How do you open and close GL periods, and what statuses can a period have?", "**Why they ask:** a basic close question.\n\n**Answer:**\n\"The statuses are Never Opened, Future Enterable, Open, Closed and Permanently Closed. I open the next period in Manage Accounting Periods or with the Open Period process. In a Future Enterable period, journals can be entered but not posted. I close the period once all subledgers have transferred and all journals are posted and reconciled. A Closed period can be reopened; Permanently Closed can't, so I only use it after audit sign-off. Subledgers like AP, AR and Assets have their own periods, and they close before GL.\"\n\nTip: Explain when you'd use Permanently Closed. It shows care with irreversible steps.", "B", null, null, {"f":["Why use Future Enterable status?","It lets users enter journals for next period, like accruals, without opening it for posting. They post once the period opens."]}],
["General Ledger", "What is the difference between a primary ledger, a secondary ledger and a reporting currency?", "**Why they ask:** a core design question.\n\n**Answer:**\n\"The primary ledger is the main book of record for a legal entity. A secondary ledger is a parallel ledger that can differ in chart of accounts, calendar, currency or accounting method. It's used for local GAAP vs IFRS or US GAAP, or for a different statutory chart, and it can be kept at subledger, journal or balance level. A reporting currency has the same chart, calendar and method as the primary; only the currency is different. So my rule of thumb: if only the currency differs, it's a reporting currency; if anything else differs, it's a secondary ledger.\"\n\nTip: Give the rule of thumb. It answers the question in one sentence.", "D", null, null, {"t":1,"f":["When would you use a reporting currency instead of a secondary ledger?","When only the currency differs. A reporting currency is a copy of the primary ledger's balances or journals converted to another currency, like EUR for a parent. If the chart of accounts, calendar or accounting method differs — say IFRS versus US GAAP — you need a secondary ledger instead."]}],
["General Ledger", "Explain revaluation and translation in GL.", "**Why they ask:** people often confuse the two.\n\n**Answer:**\n\"Revaluation adjusts foreign-currency balances to the period-end rate. For example, a EUR bank account in a USD ledger is revalued, and the difference goes to unrealized gain or loss, usually reversed next period. Translation converts the whole ledger's balances into another currency for reporting or consolidation: balance sheet at the period-end rate, P&L at the average rate, equity at historical rates, and the difference goes to CTA. Revaluation comes first, after all foreign-currency transactions are posted, then translation.\"\n\nTip: State the order: revalue, then translate. It's what they want to hear.", "D", null, null, {"f":["Where does unrealized gain from revaluation get reversed?","Revaluation journals are usually set to reverse at the start of the next period, so the following month revalues fresh from the original balances."]}],
["General Ledger", "How would you set up a recurring allocation, for example rent allocated by headcount?", "**Why they ask:** a practical allocation question.\n\n**Answer:**\n\"In Fusion I'd build it as a Calculation Manager allocation rule. The source, or pool, is the rent account balance for the period. The basis is a statistical account holding headcount by cost center, loaded every month from HR. The target is rent expense on each receiving cost center, in proportion to headcount. The offset is a credit back to the source cost center. It generates each month, on a schedule or by hand, and someone reviews it before posting. In EBS the equivalent is MassAllocations. I test it first with a small set of numbers I can check by hand.\"\n\nTip: Mention testing with numbers you can check by hand. It shows care with allocations.", "D", null, null, {"f":["What happens if headcount isn't updated before the allocation runs?","Rent goes out on last month's headcount, so departments are charged wrongly. The statistical load is a close checklist step before allocations."]}],
["Accounts Payable", "Explain the Procure-to-Pay flow and where AP fits in.", "**Why they ask:** a basic question, but they listen for whether you connect the steps to the accounting.\n\n**Answer:**\n\"Procurement starts it: a requisition becomes a purchase order. Receiving records the goods or services. Then AP takes over: the invoice is entered or imported and matched to the PO and receipt, validation checks matching, tax and holds, the invoice is approved, and it is paid through a payment process request. Finally Create Accounting sends the entries to the General Ledger through Subledger Accounting.\"\n\n**Worked example: the entries for a $1,000 purchase**\n- Receipt: Dr Inventory or Expense 1,000 / Cr Receipt Accrual 1,000\n- Invoice: Dr Receipt Accrual 1,000 / Cr AP Liability 1,000\n- Payment: Dr AP Liability 1,000 / Cr Cash Clearing 1,000\n- Bank reconciliation: Dr Cash Clearing 1,000 / Cr Cash 1,000\n\nTip: Walking through the four entries without being asked separates a finance consultant from a system user.", "B", null, null, {"t":1,"f":["What happens in GL when a PO receipt is entered?","With receipt accrual on, Oracle books Dr Expense or Inventory, Cr Receipt Accrual when goods are received. When the AP invoice is matched and accounted, it books Dr Receipt Accrual, Cr Supplier Liability. So for a $1,000 receipt, the accrual sits at $1,000 until the invoice clears it to zero."]}],
["Accounts Payable", "What is the difference between 2-way, 3-way and 4-way matching?", "**Why they ask:** a core control question. They want the definitions and when you would use each one.\n\n**Answer:**\n\"It's how many documents the invoice must agree with before it can be paid. Two-way checks the invoice against the PO, quantity and price, which suits services or low-risk items. Three-way adds the receipt, so we only pay for what was actually received. Four-way adds inspection or acceptance, used where quality checks matter, like lab supplies or parts that can be rejected. The match level is set on the PO schedule, defaulted from the supplier, item or purchasing options. Anything outside tolerance goes on hold.\"\n\n**Example:** PO for 100 units at $10. Receipt for 90. Invoice for 100 at $10.\n- 2-way: passes (invoice agrees with the PO).\n- 3-way: quantity received hold, because only 90 were received.\n\nTip: The worked example shows you understand the control, not just the terms.", "B", null, null, {"f":["Where do you set which matching level a PO uses?","On the PO schedule, defaulted from the item, supplier or purchasing options, with values like two-way or three-way."]}],
["Accounts Payable", "What are invoice holds and how do you release them?", "**Why they ask:** holds drive most AP work, and how you handle them shows if you understand the controls.\n\n**Answer:**\n\"A hold stops an invoice from being paid until something is fixed. The common ones are matching holds like quantity ordered, quantity received, price and amount; variance holds on distributions or tax; account holds for an invalid account; supplier or site holds; and manual holds placed by users. System holds release on their own once the cause is fixed and the invoice is validated again, for example after the goods are received or the PO price is corrected. Manual-releasable holds need an authorized user to release them with a reason. To keep holds moving, I route each type to its owner with the holds resolution workflow.\"\n\n- **Matching:** quantity ordered, quantity received, price, amount.\n- **Variance:** distribution or tax variance.\n- **Account:** invalid distribution account.\n- **Supplier or site:** payment hold.\n- **Manual:** placed by users.\n\nTip: Stress that you fix the cause, not just release the hold. Releasing holds without fixing them is an audit finding.", "B", null, null, {"t":1,"f":["Who should release a price hold?","The buyer, because they own the PO price. If the invoice says $10.50 and the PO says $10, the buyer either confirms the supplier is right and updates the PO, or tells AP to short-pay or get a credit memo. AP shouldn't force-release price holds on its own."]}],
["Accounts Payable", "What types of invoices can you enter in Payables?", "**Why they ask:** a foundation check. A wrong invoice type means wrong accounting or reporting.\n\n**Answer:**\n\"The everyday one is the standard invoice. Credit memos are credits from the supplier, debit memos are credits we raise against the supplier ourselves. Prepayments are advances that get applied to invoices later. Withholding tax invoices are created automatically for amounts withheld. Expense reports come in from Oracle Expenses for employee reimbursement. Payment requests pay people who aren't suppliers, like customer refunds. And interest invoices are created automatically for late-payment interest if that's set up.\"\n\n- **Standard**, **Credit memo**, **Debit memo**\n- **Prepayment**\n- **Withholding tax** (system-created)\n- **Expense report** (from Expenses)\n- **Payment request** (non-supplier payees)\n- **Interest** (system-created)\n\nTip: Mention the difference between a credit memo and a debit memo clearly. Many candidates mix them up.", "B", null, null, {"f":["When would you use a debit memo instead of waiting for a credit memo?","When we've agreed a credit with the supplier, like for returned goods, and want to record it immediately rather than wait for their paperwork."]}],
["Accounts Payable", "How does a prepayment work in AP?", "**Why they ask:** prepayments touch the balance sheet, and unapplied prepayments are a classic audit issue.\n\n**Answer:**\n\"First you enter a prepayment invoice, validate it and pay it. That books a prepaid asset instead of an expense. When the real invoice arrives, you apply the prepayment to it, which reduces what you still owe and moves the amount out of the prepaid account. Temporary prepayments are meant to be applied to invoices. Permanent ones, like a lease deposit, are not. Oracle can also apply prepayments automatically during validation if that's set up. At month-end, I reconcile the prepaid account so nothing sits unapplied.\"\n\n**Worked example: $5,000 advance, then a $12,000 invoice**\n- Prepayment invoice: Dr Prepaid Expense 5,000 / Cr AP Liability 5,000\n- Payment: Dr AP Liability 5,000 / Cr Cash 5,000\n- Apply to the $12,000 invoice: Dr Expense 12,000 / Cr AP Liability 7,000 / Cr Prepaid Expense 5,000\n\nTip: Mention reconciling the prepaid account. Unapplied prepayments are a common audit question.", "B", null, null, {"f":["Why can't you pay a prepayment-applied invoice for the full amount?","Applying the prepayment reduces the amount due, so only the net is paid and the prepaid asset is relieved."]}],
["Accounts Payable", "What is a Payment Process Request (PPR)?", "**Why they ask:** every payment in Fusion goes through a PPR, so you need to explain it clearly.\n\n**Answer:**\n\"A PPR is how Fusion selects invoices and pays them in bulk. You give it selection criteria: pay-through date, business unit, supplier, payment method, pay group and currency. Then the payment and processing options: which bank account, which payment process profile, and whether to stop for review. It runs in steps: select the invoices, review the proposed payments, build the payments, create the payment file or print checks, and transmit to the bank. Most companies schedule them, for example a daily ACH run and a weekly check run. The payment process profile decides the file format, such as NACHA or ISO 20022, and how it's sent.\"\n\n1. Select invoices.\n2. Review proposed payments (optional stop).\n3. Build payments.\n4. Create the payment file or print checks.\n5. Transmit to the bank.\n\nTip: Mention scheduled PPR templates. Real companies don't submit PPRs by hand every day.", "B", null, null, {"t":1,"f":["What do you review before confirming a PPR?","The proposed payments: total amount against cash available, any unusually large payments, new or changed supplier bank accounts, suppliers on hold and duplicate amounts. Once the PPR is confirmed and the file is formatted and sent, a change means voiding payments, so this review is the last cheap control point."]}],
["Accounts Payable", "How do you handle 1099 reporting in Oracle Payables?", "**Why they ask:** 1099 errors cost penalties and go straight to the IRS. They want to see you start long before January.\n\n**Answer:**\n\"It starts with supplier setup: US suppliers who need 1099s are marked federal reportable, with their taxpayer ID and income tax type, for example NEC for services. That income tax type defaults onto invoice distributions. During the year, if suppliers were set up wrong, I fix the history with the Update and Report Income Tax Details process. At year-end I run the US 1099 Report, the Invoice Exceptions and Supplier Exceptions reports, and then produce the electronic file or the printed forms.\"\n\n- **Setup:** federal reportable, taxpayer ID, income tax type (NEC, MISC).\n- **During the year:** Update and Report Income Tax Details for corrections.\n- **Year-end:** US 1099 Report, exception reports, 1099 Electronic Media.\n\nTip: Say you review the exception reports in December, not January. It shows you've been through a real year-end.", "D", null, null, {"f":["What if a supplier's 1099 type was wrong all year?","Update the supplier, then run the Update Income Tax Details process to correct historical invoice distributions before running the 1099 reports."]}],
["Accounts Receivable", "Explain the Order-to-Cash flow and where AR fits in.", "**Why they ask:** a warm-up question for every finance or O2C role.\n\n**Answer:**\n\"It starts with the customer set up with an account and bill-to and ship-to sites. Sales books an order in Order Management and the warehouse ships it. The shipment flows to AR through AutoInvoice and becomes an invoice. The customer pays, and we record the receipt manually, through lockbox, or from the bank statement, then apply it to the invoice. Anything unpaid goes to collections. Finally Create Accounting sends the entries to GL. AR owns the middle of that chain: invoicing, cash application and collections.\"\n\nAccounting:\n- Invoice: Dr Receivable, Cr Revenue, Cr Tax.\n- Receipt: Dr Cash, Cr Receivable.\n\nTip: Give the two journal entries at the end. It shows you think like an accountant, not only a system user.", "B", null, null, {"t":1,"f":["What links a shipped order to an AR invoice?","When the order line ships, fulfillment sends the billing data — customer, item, quantity, price and the order reference — into the AutoInvoice interface. AutoInvoice then creates the invoice using the transaction source and transaction type, and the order number is kept as a reference so you can trace invoice back to order."]}],
["Accounts Receivable", "What is AutoInvoice?", "**Why they ask:** AutoInvoice is the main way invoices get into AR. Every AR interview touches it.\n\n**Answer:**\n\"AutoInvoice is the program that imports billing lines from other systems and turns them into invoices, credit memos and debit memos. In Fusion the lines come from Order Management, Projects, or a file through FBDI; in EBS they go into RA_INTERFACE_LINES_ALL. The transaction source controls validation and defaults. Grouping rules decide which lines become one invoice, and line ordering rules sort them. AutoAccounting, together with SLA in Fusion, derives the revenue and receivable accounts. Lines that fail stay in the interface with an error, and you fix them and resubmit. On a busy project it's normal to process tens of thousands of lines a night, so the error handling is as important as the setup.\"\n\nTip: Cover source, grouping, accounting and errors. Those are the four follow-up questions they'll ask.", "B", null, null, {"f":["What's the most common AutoInvoice failure?","Invalid or inactive customer sites or accounts, followed by missing accounting setup or invalid items."]}],
["Accounts Receivable", "What is the customer structure in Oracle (party, account, site)?", "**Why they ask:** a basic question, but bad customer data causes most AR errors, so they want to see you understand the model.\n\n**Answer:**\n\"Oracle uses the Trading Community Architecture. The party is the real company or person, say ACME Corp. The customer account is our business relationship with that party, with terms, a profile and credit settings, and one party can have several accounts, for example one for ACME's US business and one for Canada. Each account has sites, which are addresses, and each site has site uses, like bill-to and ship-to. The customer profile carries the credit limit, collector, statement and dunning settings. Because the party is shared, the same company can be both a customer and a supplier.\"\n\n- **Party:** the real-world entity.\n- **Account:** the relationship (terms, credit).\n- **Site and site use:** the address and what it's for.\n- **Profile:** credit, collector, dunning.\n\nTip: Give the one-party-two-accounts example. It shows you've designed customer data, not just entered it.", "B", null, null, {"f":["Why can one party have multiple customer accounts?","Different business relationships, like a parent buying from two divisions with different terms or currencies."]}],
["Accounts Receivable", "How do you apply a receipt, and what happens with unapplied or on-account cash?", "**Why they ask:** cash application is core AR work. They want to hear the different states of cash and why they matter.\n\n**Answer:**\n\"I create the receipt against a receipt method and bank account, manually, from lockbox or from the bank statement, then apply it to one or more open invoices. If it covers only part, the invoice stays open for the rest. Any money I can't match yet is unapplied: we know the customer but not which invoices. On-account is a deliberate choice to leave the money on the customer's account, like a deposit or an overpayment we'll use later. Unidentified means we don't even know the customer yet. In Fusion, AutoMatch uses the remittance details to apply receipts automatically, so people only work the exceptions.\"\n\n- **Unapplied:** customer known, invoices not yet.\n- **On-account:** parked on purpose.\n- **Unidentified:** customer unknown.\n\nTip: Explaining the three states cleanly is the whole answer. Add that you'd watch the unapplied balance every week.", "B", null, null, {"t":1,"f":["What's the difference between unapplied and on-account cash?","Unapplied is cash we've received but haven't matched to anything yet — usually because we don't know which invoice it's for. On-account is a deliberate choice to hold the cash as a customer credit to use later, like a deposit. Unapplied should be worked down daily; on-account is a known balance."]}],
["Accounts Receivable", "What is the difference between an adjustment and a credit memo?", "**Why they ask:** people often mix these up. The right choice affects revenue, tax and what the customer sees.\n\n**Answer:**\n\"A credit memo corrects the billing. It's a transaction document, usually sent to the customer, and it reverses revenue and tax, for example for a return or a pricing error. An adjustment changes the invoice balance without saying the billing was wrong, for small write-offs, bad debt or rounding. It uses a receivables activity for the GL account and is limited by the user's approval limit. So if we billed $1,000 but should have billed $900, that's a credit memo. If we billed correctly but the customer paid $998 and we won't chase $2, that's an adjustment.\"\n\nTip: The rule of thumb: billing was wrong → credit memo; the money won't be collected → adjustment. Say it in one line.", "B", null, null, {"f":["Why not use adjustments to fix pricing errors?","Adjustments don't reverse revenue and tax properly or produce a customer document, so pricing errors should be credit memos."]}],
["Fixed Assets", "How does an asset get created from an AP invoice?", "**Why they ask:** a basic question, but it covers the most common path into Assets.\n\n**Answer:**\n\"AP charges the invoice line to an asset clearing account, or flags it Track as Asset. After the invoice is validated and accounted, Create Mass Additions sends the line to the Mass Additions queue in Assets. There, someone reviews it: assigns the category, location, cost center and date placed in service, and merges or splits lines if needed. Then Post Mass Additions creates the asset. Depreciation starts based on the date placed in service and the prorate convention.\"\n\nTip: Keep it as five clear steps. It's a process question, so answer it as one.", "B", null, null, {"t":1,"f":["What's a common reason an asset never gets created?","The invoice line was charged to a regular expense account instead of the asset clearing account, so Create Mass Additions never picks it up. I'd check the distribution account, and make sure the PO or the invoice defaults to the clearing account for capital items above the threshold, say $5,000."]}],
["Fixed Assets", "What are the main asset transactions in Oracle Assets?", "**Why they ask:** a basic question to check you know the asset life cycle.\n\n**Answer:**\n\"An addition creates the asset. An adjustment changes its cost, life or method. A transfer moves it to another location, cost center or employee. A reclassification changes its category. A retirement removes it, fully or partly, with proceeds of sale and cost of removal, and Oracle calculates the gain or loss. A reinstatement undoes a retirement in the same period. Where the accounting standard requires it, there's also revaluation and impairment. Every one of these creates accounting through SLA after Create Accounting.\"\n\nTip: Follow the life of an asset from birth to retirement. It's easier to remember and to listen to.", "B", null, null, {"f":["Which of those transactions changes depreciation expense account?","A transfer to a new cost center, because the expense account comes from the asset assignment."]}],
["Fixed Assets", "What is depreciation prorate convention?", "**Why they ask:** prorate conventions explain why first-month depreciation looks wrong to new users.\n\n**Answer:**\n\"The prorate convention decides when depreciation starts, based on the date placed in service. With following month, an asset added on March 10 starts depreciating in April. With mid-month, it gets half a month in March. With actual month, it gets a full month in March. With half-year, common in US tax books, it gets half a year of depreciation in the first year no matter which month it was added. The convention is set on the category for each book and defaults to the asset.\"\n\nTip: Use one date and walk it through each convention. It makes the answer easy to follow.", "D", null, null, {"f":["How does convention affect year-one depreciation?","It changes how many months are depreciated in the first year, so an asset placed in December might get one month or none depending on the convention."]}]
]);

QB["ora-fc-fin"] = (QB["ora-fc-fin"] || []).concat([
["Cash Management", "How does bank statement reconciliation work in Oracle Cash Management?", "**Why they ask:** the core Cash Management question.\n\n**Answer:**\n\"Statements are loaded from bank files like BAI2, MT940 or CAMT.053, or entered by hand. Autoreconciliation then matches statement lines to AP payments, AR receipts and journals using the reconciliation rule set, on reference, amount and date within tolerances. Whatever doesn't match, I reconcile manually. For lines that are just bank fees or interest, transaction creation rules create external transactions automatically. When a payment is reconciled, Fusion books Dr Cash Clearing, Cr Cash, and that goes to GL.\"\n\nTip: Mention the clearing entry at the end. It shows you know reconciliation drives accounting.", "B", null, null, {"f":["What's a good autoreconciliation rate to aim for?","Above 90%. Below that, I look for patterns like bank fees or batch deposits to fix with rules."]}],
["Cash Management", "What is the difference between a bank, a branch and a bank account in Oracle?", "**Why they ask:** a basic setup question.\n\n**Answer:**\n\"The bank is the institution, like JPMorgan Chase. The branch is a specific branch with its routing number or BIC. The bank account is our company's account at that branch, with the account number, currency, cash and cash clearing GL accounts, and its uses, like Payables, Receivables or Payroll. A bank account is owned by a legal entity and can be used by the business units that are given access to it.\"\n\nTip: Mention legal entity ownership. It's the part that drives intercompany questions later.", "B", null, null, {"f":["Who owns the bank account in Fusion?","A legal entity, and business units are then granted access to use it for payables or receivables."]}],
["Subledger Accounting", "What is Create Accounting and why does it matter?", "**Why they ask:** a basic question for anyone working in Fusion finance.\n\n**Answer:**\n\"Subledger transactions, like invoices, receipts and asset additions, don't reach GL by themselves. Create Accounting runs Subledger Accounting to build the journal entries from those events, and can then transfer and post them to GL. It runs in draft, which you can review and change, or final, which is locked. Errors, like an invalid account, show up in the execution report, and you fix them and rerun. I schedule it daily rather than only at month-end, so problems surface early instead of on the last day of close.\"\n\nTip: Say \"daily, not month-end\". It's the practical point that shows experience.", "B", null, null, {"t":1,"f":["What's the difference between Create Accounting in draft and final?","Draft accounting creates entries you can review but doesn't send anything to GL, and you can rerun it after fixing data. Final accounting locks the entries, so the transaction can't change, and can transfer and post to GL. Most period-end runs are final; draft is for checking first."]}],
["Subledger Accounting", "How do you find out why a transaction did not create accounting?", "**Why they ask:** a common support question with a clear method.\n\n**Answer:**\n\"I check the Create Accounting execution report for the error, and the transaction's accounting status, for example an invoice showing Unaccounted. The common causes are: the transaction isn't validated or approved; the subledger period is closed; the account combination is invalid or disabled; a cross-validation rule failed; or a mapping set has no value for this case. Review Subledger Journal Entries shows any draft entries with errors. Once I fix the cause, I rerun Create Accounting for that transaction or batch.\"\n\nTip: Give the list of causes in the order you'd check them. It's the method they want.", "D", null, null, {"t":1,"f":["What if the error is an invalid account combination?","Look at cross-validation rules and whether a segment value is inactive, end-dated or not allowed for posting. For example, a cost center created in GL but not enabled for the account combination. Fix the value or the rule, then rerun Create Accounting for just those transactions."]}],
["Tax", "How is tax calculated on transactions in Oracle Fusion?", "**Why they ask:** a basic tax question for finance consultants.\n\n**Answer:**\n\"Fusion Tax uses a hierarchy: tax regime, like US Sales Tax or UK VAT, then tax, tax status, tax rate and tax jurisdiction. Tax rules decide whether a tax applies and which rate, based on the parties, locations, product and transaction details. Parties need tax profiles and registrations. Tax is calculated on AP invoices, AR transactions and purchase orders and shown on separate tax lines with their own accounts. For US sales tax, many companies use a partner like Vertex or Avalara instead.\"\n\nTip: Mention the partner option for the US. It's the common real-world setup.", "D", null, null, {"f":["How do you test a new tax rule?","Use the tax simulator with sample transactions to see which rule and rate apply before going live."]}],
["Expenses", "Explain the Oracle Expenses flow.", "**Why they ask:** Expenses touches every employee, so it's often the most visible part of a Financials rollout.\n\n**Answer:**\n\"The employee creates an expense report on the web or the mobile app and attaches receipts. Corporate card transactions import automatically. Expense policies check limits, like a daily meal cap, and whether receipts are required. The report goes to the manager for approval, plus anyone else the approval rules add. Auditors review a sample or the reports picked by audit rules. Once approved, Process Expense Reimbursements creates Payables invoices, and they're paid through a payment run or through payroll. The accounting defaults from the employee's cost center and the expense type.\"\n\n1. Create the report, attach receipts (card transactions import).\n2. Policy checks.\n3. Manager approval.\n4. Audit.\n5. Payables invoice created and paid.\n\nTip: Mention the mobile app and receipt capture. Adoption depends on how easy it is for employees, and interviewers know that.", "B", null, null, {"f":["How does an expense report get paid?","After approval and audit, it becomes a Payables invoice for the employee and is paid in a normal payment run or reimbursed with payroll."]}],
["Security", "How is security structured in Oracle Fusion Financials?", "**Why they ask:** every finance consultant touches security, and SoD is an audit topic.\n\n**Answer:**\n\"Fusion security has two parts: what you can do and which data you can do it on. What you can do comes from job roles, like Accounts Payable Specialist, which contain duty roles and privileges. Which data comes from data access: data access sets for ledgers in GL, and business unit or ledger data roles for subledgers, set in Manage Data Access for Users. Abstract roles like Employee and Line Manager cover self-service. Custom roles are created by copying seeded roles in the Security Console; I never edit seeded roles. And I check segregation of duties, for example the person who creates suppliers shouldn't be able to pay them.\"\n\nTip: Use the \"what vs which data\" split. It makes a complex topic simple.", "B", null, null, {"f":["Why does a user have a role but still see nothing?","They're missing data access, like the business unit or ledger, for that role in Manage Data Access for Users."]}],
["Reporting", "What reporting tools are available in Oracle Fusion Financials?", "**Why they ask:** to see if you'll pick the right tool for a reporting request.\n\n**Answer:**\n\"OTBI is self-service, ad-hoc analysis on real-time data using subject areas, quick to build but with basic formatting. BI Publisher is for pixel-perfect documents like checks, invoices and statements, and for complex SQL-based extracts. Financial Reporting and Smart View report GL balances from the Essbase cube, with Smart View in Excel for ad-hoc and formatted statements. Account Monitor and Account Inspector give quick balance views and drill-down. And infolets and dashboards serve managers. My rule of thumb: ad-hoc goes to OTBI, documents and extracts to BIP, financial statements to Financial Reporting or Smart View.\"\n\nTip: End with the rule of thumb. It answers the follow-up before it's asked.", "B", null, null, {"f":["Which tool would you use for a monthly P&L package?","Financial Reporting or Smart View, because they read the balances cube and handle formatted financial statements."]}],
["Reporting", "How do you reconcile Payables to the General Ledger?", "**Why they ask:** AP-to-GL reconciliation is a monthly control.\n\n**Answer:**\n\"I run the Payables to Ledger Reconciliation report, which compares the AP trial balance to the GL liability balance by period. If there's a difference, I look at unaccounted transactions, accounting that wasn't transferred or posted, manual journals posted straight to the liability account, and transactions accounted in a different period. The goal is that the open invoices in the AP trial balance equal the GL liability account. And I fix the cause, not just book an adjustment. The same approach works for AR and Assets.\"\n\nTip: Say \"fix the cause, not just adjust\". It's what controllers want to hear.", "D", null, null, {"t":1,"f":["What's a typical reason for a difference you've found?","A manual journal posted directly to the AP liability account in GL, which never touched the subledger. The AP trial balance says $2.1 million, GL says $2.15 million, and the $50,000 difference is that journal. That's why I recommend locking control accounts so only the subledger can post to them."]}],
["Period Close", "What steps would you follow to close the Payables period?", "**Why they ask:** a practical close question for finance consultants.\n\n**Answer:**\n\"I make sure all invoices for the period are entered and validated, and holds that matter are resolved. I finish the period's payment runs. I run Create Accounting, transfer to GL, and clear any accounting errors. I review the unaccounted transactions and exception reports. If there are transactions that can't be accounted in time, I sweep them to the next period where that's appropriate. Then I close the Payables period, open the next one, and reconcile the AP trial balance to GL.\"\n\nTip: Mention the sweep option. It shows you've closed a period under pressure.", "B", null, null, {"f":["What happens to invoices left unaccounted at close?","Payables won't close until they're accounted or swept to the next period."]}],
["Period Close", "What is the typical order of closing subledgers before GL?", "**Why they ask:** close sequence errors cause rework.\n\n**Answer:**\n\"Purchasing and receiving first, so receipts and accruals are complete. Then Payables, with invoices and payments accounted. Then Receivables. Then Cash Management, with bank statements reconciled. Then Assets, which needs Payables done first so additions come through, followed by depreciation. Then Projects, Inventory and Cost if they're used. GL closes last: post, revalue, translate, consolidate and close.\"\n\nTip: Say why Assets follows Payables. Dependencies are the point of the question.", "B", null, null, {"f":["Why does Cash Management close after AP and AR?","Bank reconciliation depends on payments and receipts being final in their subledgers."]}],
["Data Loads", "What is FBDI and how do you use it?", "**Why they ask:** FBDI is the main bulk load tool in Fusion.\n\n**Answer:**\n\"File-Based Data Import is the standard way to load bulk data. I download the Excel template for the object, like AP invoices, journals or suppliers, from Oracle's documentation. I fill it in and generate the CSV zip file. Then I upload it to UCM, run Load Interface File for Import, then the import process, for example Import Payables Invoices. Errors show in the import report or the interface correction pages, and I fix and reload. Other options are ADFdi spreadsheets for journals and some objects, and REST APIs for integrations.\"\n\nTip: Name the two-step process: load interface, then import. It shows you've done it.", "B", null, null, {"f":["What do you check after an FBDI load?","The import report for errors, then counts and totals compared with the source file."]}],
["Testing", "How do you test a configuration change before moving it to production?", "**Why they ask:** untested changes cause production problems.\n\n**Answer:**\n\"I write test scenarios with expected results, including the accounting. I test in a non-production environment: the normal path, edge cases and things that should fail. I check related processes, for example a payment terms change affects due dates and payment runs. A business user runs UAT and signs off. I move the change with a configuration package or documented manual steps, keeping evidence for audit. And after the next quarterly update, I rerun the key regression tests.\"\n\nTip: Mention checking related processes. It's where surprises come from.", "B", null, null, {"f":["What evidence do you keep from testing?","Test scripts with results and screenshots of the accounting, signed off by the business owner, so the change can be audited."]}],
["Support", "A user says they cannot see a business unit when entering invoices. How do you troubleshoot?", "**Why they ask:** a common support ticket. They want a structured approach.\n\n**Answer:**\n\"I go in order. Role: does the user have an AP role at all? Data access: in Manage Data Access for Users, is that role granted for this business unit? Setup: does the BU use the Payables business function and is it set up correctly? Refresh: I ask the user to sign out and back in, or wait for the role refresh. And if many users have the same problem, I check whether a recent security change or quarterly update caused it.\"\n\nTip: Say the order out loud: role, data access, setup, refresh. Interviewers like the structure.", "B", null, null, {"f":["What if all of that looks right?","Check whether the user's session has refreshed roles, and run the security processes like Import User and Role Application Security Data."]}],
["Support", "How do you handle a production support ticket you have never seen before?", "**Why they ask:** support work is full of new problems.\n\n**Answer:**\n\"First I reproduce it and capture the details: user, transaction, screenshots, error message and when it started. I check what changed recently, configuration, an update or data. I search My Oracle Support for the error and known bugs, and check the release notes. I test a fix in a lower environment. If it's a product bug, I raise an SR with Oracle, with steps and logs. I keep the user updated, and I document the fix in the knowledge base.\"\n\nTip: Mention \"what changed recently\". It solves most new problems.", "B", null, null, {"f":["When would you raise an SR with Oracle?","When it looks like a product bug or I can't find a cause after checking setup, data and recent changes."]}],
["Behavioral", "Tell me about yourself.", "**Why they ask:** the opener. They want a clear, relevant story in about 90 seconds.\n\n**Answer (example, use your own facts):**\n\"I'm an Oracle Financials consultant with about three years' experience, mainly in Fusion AP, AR and GL. On my last project I supported a Fusion implementation for a mid-size manufacturer: I configured payables options, payment terms and payment process profiles, built test scripts, and ran the AP part of UAT. Since go-live I've handled support tickets and month-end close issues, which taught me a lot about subledger accounting. Now I'm looking for a role where I can own a module end to end, which is why this position interests me.\"\n\nTip: Use present, past, why this role. Tailor the last line to the job description.", "B", null, null, {"t":1,"f":["How long should your answer be?","About 90 seconds. Start with your current role in one line, give two achievements with numbers — like 'led the Fusion GL design for three ledgers' — and finish with why this role fits. Longer than two minutes and the interviewer stops listening."]}],
["Behavioral", "Describe a time you made a mistake on a project. What happened?", "**Why they ask:** they want honesty and what you learned.\n\n**Answer (example):**\n\"I changed a payment term setup in test but missed one business unit when I documented it for production. After migration, invoices for that BU had the wrong due dates. I caught it in my post-migration check, told my lead straight away, fixed the setup, and corrected the affected invoices before the payment run, so no payments went out late or early. Since then I use a migration checklist and compare setups between environments after every move.\"\n\nTip: Own it, show how you caught it, and name the process you changed.", "B", null, null, {"f":["What process change did that lead to?","I started using a configuration workbook for every change with all business units listed, reviewed by a second person before migration."]}],
["Behavioral", "How do you explain a technical issue to a non-technical finance user?", "**Why they ask:** consultants spend a lot of time explaining.\n\n**Answer:**\n\"I start with the business impact, like 'the invoice can't be paid until we receive the goods', not system terms. I use their words, approval, due date, account, and no table names. I tell them what they need to do and by when, in a few steps, and show it on screen or with a screenshot. Then I check they understood and follow up. For example, I'd explain a quantity hold as 'the invoice says 10 units, but we've only received 8'.\"\n\nTip: Use the 10-vs-8 example. It shows you can translate.", "B", null, null, {"f":["Give an example sentence you'd use.","This invoice is on hold because the warehouse hasn't recorded receiving the goods; once they do, it will release on the next validation run."]}],
["General Ledger", "What are journal categories and sources used for?", "**Why they ask:** sources and categories drive approvals, reporting and automation.\n\n**Answer:**\n\"The journal source says where a journal came from, like Manual, Payables, Receivables, Spreadsheet, or a custom source for an integration. The category says what kind of entry it is, like Accrual, Adjustment, Purchase Invoices or Receipts. They're used in journal approval rules, in reporting and audit, for example showing all manual journals, in reversal options, in AutoPost criteria and in document sequencing.\"\n\nTip: Recommend a custom source per integration. It makes audit and reconciliation much easier.", "B", null, null, {"f":["Why do categories matter for automation?","Reversal rules, approval rules and conversion rules for secondary ledgers are often set by category."]}],
["General Ledger", "What is the difference between Smart View and Financial Reporting Studio?", "**Why they ask:** to see if you know which reporting tool to suggest.\n\n**Answer:**\n\"Smart View is an Excel add-in that queries the GL balances cube. It's great for ad-hoc analysis, pivoting and building Excel reports with live data and drill-down. Financial Reporting Studio and the Financial Reporting Center produce formatted, governed reports like the P&L and balance sheet for many users, though Oracle is moving those toward Narrative Reporting and Smart View-based reports. Both read the same Essbase cube, which updates when journals post.\"\n\nTip: Mention Oracle's move away from FR Studio. It shows you're current.", "D", null, null, {"f":["Which would you give a controller who wants an Excel P&L?","Smart View, because they can build it in Excel with live data and drill-down."]}],
["Accounts Payable", "What is the difference between a supplier, a supplier site and a site assignment?", "**Why they ask:** supplier setup is behind many \"I can't find the supplier\" tickets. The structure tells them if you understand multi-BU setups.\n\n**Answer:**\n\"The supplier is the company itself: name, tax ID, type. Addresses hold the physical locations. A supplier site is an address used for purchasing or paying, and it's created per procurement business unit, carrying payment terms, payment method, pay group and holds. A site assignment then lets a client business unit use that site. So in a shared services model, one procurement BU owns the site, and assignments let all the other BUs invoice against it. When a user says they can't find a supplier in their BU, the first thing I check is the site assignment.\"\n\n**Example:** Supplier ABC Corp → site ABC-NEWARK in the US procurement BU → assigned to US East, US West and Canada BUs.\n\nTip: The \"can't find the supplier\" example is the line that lands. It shows real support experience.", "B", null, null, {"f":["Why are sites created per procurement BU?","Each procurement BU manages its own supplier sites, which can then be assigned to client BUs that invoice and pay."]}],
["Accounts Payable", "How do payment terms and discounts work in AP?", "**Why they ask:** discounts are real money, and terms setup decides when cash leaves the company.\n\n**Answer:**\n\"Payment terms set when an invoice is due and whether there's an early-payment discount. The classic is 2/10 Net 30: 2% off if paid within 10 days, otherwise the full amount in 30. Terms default from the supplier site or the PO onto the invoice, and the terms date basis, like invoice date or goods received date, sets the start date. Oracle creates installments from the terms, and the payment run picks them up when due. If the discount option is enabled and the payment date falls in the discount window, the discount is taken automatically.\"\n\n**Worked example:** $50,000 invoice dated March 1, terms 2/10 Net 30.\n- Paid by March 11: pay $49,000, discount $1,000.\n- Otherwise: pay $50,000 by March 31.\n\nTip: Mention the terms date basis. Using goods received date instead of invoice date is a quiet way to protect cash.", "B", null, null, {"f":["Is taking a 2/10 Net 30 discount worth it?","Usually yes: 2% for paying 20 days early is an annualized return of about 37%, far above most borrowing costs."]}],
["Behavioral", "Why do you want to grow in Oracle Finance consulting?", "**Why they ask:** to see motivation beyond pay.\n\n**Answer:**\n\"I like that ERP sits where finance and technology meet. A good setup decision can save the finance team hours every month, and I enjoy seeing that. I want to deepen my GL, SLA and close knowledge and move from configuring to designing solutions. I'm also working toward the Oracle Financials Cloud implementation certification.\"\n\nTip: Show curiosity about accounting, not just the software.", "B", null, null, {"f":["Which area would you deepen first?","Subledger accounting, because it connects every module to GL and is where many issues come from."]}],
["Accounts Receivable", "What is the purpose of receivables activities and transaction types?", "**Why they ask:** these two setups drive most AR accounting. They want to see you know which does what.\n\n**Answer:**\n\"Transaction types classify the documents: invoice, credit memo, debit memo, chargeback, deposit. They control whether a transaction posts to GL, whether it shows in open receivables, the default receivable and revenue accounts, and which credit memo type is used when you credit it. Receivables activities are for postings that aren't invoices: adjustments, write-offs, finance charges, miscellaneous receipts, bank charges and refunds. Each one points to its own GL account. For example, a 'Small Balance Write-off' activity posts to a bad-debt expense account, and the user's approval limit controls how much they can write off.\"\n\nTip: Give one example of an activity and its account. It turns a definition into experience.", "D", null, null, {"f":["What does a receivables activity control?","The GL account for adjustments, write-offs, finance charges and similar activities."]}],
["Accounts Receivable", "How do collections and dunning work in Oracle?", "**Why they ask:** they want to see you understand the collector's day, not just the setup screens.\n\n**Answer:**\n\"In Fusion, Advanced Collections assigns each customer to a collector from the customer profile. The collector works a prioritized list in the Collections work area: they see aging, record promises to pay, log disputes and send correspondence. Scoring ranks customers by risk, and strategies decide the tasks, like a call at 10 days late for high-risk customers. Dunning sends reminder letters automatically based on aging and the dunning plan, getting firmer as the invoice gets older. Disputes create credit memo requests that route for approval. The KPIs I'd report are DSO, percent current, and collector effectiveness.\"\n\nTip: Name the KPIs. Hiring managers measure collections by numbers.", "D", null, null, {"f":["How do you keep dunning from annoying good customers?","Use strategies by risk, so low-risk customers get gentle reminders and high-risk ones get faster escalation."]}]
]);

// Added Oct 2026: more functional, Fusion platform, Redwood and AI Agent Studio questions.
QB["ora-fc-fin"] = (QB["ora-fc-fin"] || []).concat([
["Redwood", "What is Oracle Redwood and how is it different from the classic Fusion pages?", "**Why they ask:** Redwood is changing how users work.\n\n**Answer:**\n\"Redwood is Oracle's new user experience and design system for Fusion. Classic pages are built on older ADF technology, with dense forms and many tabs. Redwood pages are rebuilt with cleaner layouts, guided flows, smart defaults, better search, mobile support and built-in AI help like summaries and suggestions. Oracle is moving modules to Redwood release by release and retiring the classic pages over time, so consultants need to know both for now. Redwood pages are extended with Visual Builder Studio, not Page Composer.\"\n\nTip: Name the Redwood pages you've used, like Payables invoices or Manage Journals.", "B", null, null, {"f":["Should a company switch every page to Redwood immediately?","No. I'd enable pages after testing them, train users, and watch for gaps like missing fields or personalizations."]}],
["Redwood", "How do you turn on a Redwood page in Fusion?", "**Why they ask:** a practical admin question.\n\n**Answer:**\n\"Many Redwood pages are enabled with profile options in Manage Administrator Profile Values, usually named after the page and set at site level. Some come as opt-in features in Functional Setup Manager, and newer ones become the default in a later release. I always enable them in a test environment first, run the test scripts, check personalizations and reports, and train users before switching production.\"\n\nTip: Mention checking the quarterly What's New documents. That's where you learn what changed.", "B", null, null, {"f":["What do you test after enabling a Redwood page?","Key flows, custom fields and personalizations, and that security still restricts the data correctly."]}],
["Redwood", "A user says a field they always used is missing on the new Redwood page. What do you do?", "**Why they ask:** a common support scenario after a Redwood switch.\n\n**Answer:**\n\"First I check whether the field just moved, because Redwood often groups fields differently or puts them in a drawer or under Show More. Then I check if it was a Page Composer personalization on the classic page, because those don't carry over. If it's needed, an admin adds it back with Visual Builder Studio, showing the field, making it required or setting a default, tested in a test environment first. And I confirm integrations and reports still populate it.\"\n\nTip: Start with \"it may have moved\". It solves half these tickets in a minute.", "B", null, null, {"f":["What if the field truly isn't available on Redwood yet?","Keep the classic page for that flow if possible, log an idea or SR with Oracle, and tell the users the plan."]}],
["AI Agent Studio", "What is Oracle AI Agent Studio?", "**Why they ask:** a basic AI question for any Fusion consultant.\n\n**Answer:**\n\"AI Agent Studio is the tool inside Fusion for creating, configuring, testing and managing AI agents. Oracle delivers ready-made agents and templates, for example for payables, procurement and HR questions, that you can use or adjust. You can build your own with instructions, topics and tools that let the agent read or act on Fusion data, documents, email and outside systems. Agents follow Fusion security, acting with the user's roles and data access. And you can choose the LLM and monitor usage and quality.\"\n\nTip: Give one use case in your own area. Nobody expects a junior consultant to be an expert.", "B", null, null, {"f":["What would you configure in AI Agent Studio for a finance team?","Start with a delivered agent, like invoice inquiry, adjust its instructions and tools, test it, then roll it out to a pilot group."]}],
["AI Agent Studio", "What is the difference between an AI agent and a simple chatbot?", "**Why they ask:** a basic concept question.\n\n**Answer:**\n\"A chatbot answers questions from a script or knowledge base. An AI agent can reason about a goal and take actions with tools: look up an invoice, check a PO, draft an email, create or update a record, within rules about what it may do. In Fusion, agents run inside the application's security and can require human approval before important actions. For example, 'why is this invoice on hold?' — an agent reads the holds, PO and receipts, explains the cause and suggests the next step.\"\n\nTip: Use the invoice hold example. It shows the difference in one scenario.", "B", null, null, {"f":["What guardrails does an AI agent need?","Limited tools and data, approval before actions that change data, and logs of what it did."]}],
["AI Agent Studio", "Give an example of how an AI agent could help an AP team.", "**Why they ask:** a practical use case question.\n\n**Answer:**\n\"An invoice question agent: a supplier or internal user asks 'When will invoice 123 be paid?' and the agent reads the status, holds and next payment run and answers. A hold resolution helper explains why an invoice is on hold and who needs to act. An intake agent reads emailed invoices with document recognition and prepares them for review. People still approve payments and changes; the agent saves time on lookups and routine steps.\"\n\nTip: Say people still approve payments. It's the line AP managers need to hear.", "B", null, null, {"f":["How would you measure the agent's value?","Fewer supplier status calls to AP and faster hold resolution time."]}],
["General Ledger", "What is the difference between a journal batch, a journal and a journal line?", "**Why they ask:** a basic GL structure question.\n\n**Answer:**\n\"A batch is a group of journals posted together, like one month's accruals. A journal belongs to one ledger, period, category and currency, and must balance. A line is one debit or credit to an account combination, with a description and amount. Approval and posting usually happen at batch level, and reversals can be done per journal.\"\n\nTip: Keep it short and clear. It's a basic question, so a crisp answer is best.", "B", null, null, {"f":["Can one batch have journals in different ledgers?","Yes in some cases, but each journal belongs to one ledger, period and currency, and must balance on its own."]}],
["General Ledger", "How do recurring journals work?", "**Why they ask:** recurring journals save time every month.\n\n**Answer:**\n\"They're for entries that repeat each period with the same or a calculated amount, like rent, amortization or standard accruals. In Fusion I build them with Calculation Manager formula rules or the recurring journal option, then generate and post them each period. Amounts can be fixed or calculated from balances, for example one-twelfth of a prepaid account. I schedule generation right after the period opens so they're never forgotten.\"\n\nTip: Mention scheduling after period open. It's the practical detail.", "B", null, null, {"f":["What happens if you forget to generate a recurring journal one month?","The expense is missing for that period, so it's on the close checklist and often scheduled automatically."]}],
["Accounts Payable", "What is the difference between invoice validation and invoice approval?", "**Why they ask:** people mix them up all the time, and the design choice affects cycle time.\n\n**Answer:**\n\"Validation is the system check: matching to the PO and receipt, tolerances, tax, accounting and distribution totals. It places or releases holds. Approval is a business decision by people, like the cost center manager, routed by approval rules. An invoice normally needs both before it can be paid. The order is configurable. I usually validate first so approvers don't spend time on invoices that will go on hold anyway.\"\n\n- **Validation:** system, rule-based, creates or releases holds.\n- **Approval:** people, routed by rules.\n- **Both** are needed to pay; order is configurable.\n\nTip: Give your preferred order and the reason. Having a view is what makes this answer senior.", "B", null, null, {"f":["Can an invoice be approved but not validated?","They're separate, but payment needs both: validated with no holds and approved."]}],
["Accounts Payable", "How do you cancel an invoice, and what happens to the accounting?", "**Why they ask:** cancellation mistakes leave broken PO balances and wrong accounting.\n\n**Answer:**\n\"You can only cancel an unpaid invoice with no prepayments applied. If it's paid, the payment has to be voided first. Cancelling is done from the Invoices work area. Oracle reverses the distributions and creates cancellation accounting on the cancel date, reversing both the expense and the liability. If the invoice was matched to a PO, the quantity billed on the PO is reduced, so the PO can be invoiced again. A cancelled invoice stays in the system for audit and can't be un-cancelled, so for a small correction I'd use a credit memo instead.\"\n\n**Example:** a $2,000 invoice matched to a PO is cancelled.\n- Entry: Dr AP Liability 2,000 / Cr Expense or Accrual 2,000\n- PO quantity billed goes back down, so the correct invoice can be matched.\n\nTip: Mention that cancellation can't be undone. It shows you think before clicking.", "B", null, null, {"f":["What if the invoice was already paid?","Void the payment first, then cancel the invoice, which reverses the liability and distributions."]}],
["Accounts Receivable", "What is a customer statement vs a dunning letter?", "**Why they ask:** a basic AR question, often for junior roles.\n\n**Answer:**\n\"A statement is a summary of everything open on a customer's account, plus recent payments, sent on a regular cycle, like monthly. It's informational. A dunning letter is a reminder about overdue items only, and it usually gets firmer the later the payment is, for example a friendly reminder at 15 days, a firmer letter at 45 days, and a final notice at 90. In Fusion, statements come from Receivables and dunning comes from Collections, and both can be printed or emailed.\"\n\nTip: Give the escalation example. It shows you understand why dunning exists.", "B", null, null, {"f":["Which one should go to a customer 60 days late?","A dunning letter, because it asks for payment of overdue items specifically."]}],
["Fixed Assets", "What happens when you retire an asset?", "**Why they ask:** retirements are common and they affect the P&L.\n\n**Answer:**\n\"I choose full or partial retirement, the retirement date, proceeds of sale and cost of removal. Oracle calculates the gain or loss as proceeds minus net book value minus removal cost. So for an asset with cost $50,000 and accumulated depreciation $42,000, sold for $10,000 with $500 removal cost, the gain is $10,000 minus $8,000 minus $500, which is $1,500. I run Calculate Gains and Losses, then Create Accounting, which removes the cost and reserve and books the proceeds and the gain or loss. If it was retired by mistake, I can reinstate it in the same period.\"\n\nTip: Show the calculation with real numbers. That's what makes this answer stand out.", "D", null, null, {"f":["Where do you set the gain and loss accounts?","In the book controls, which hold the accounts for retirement gains, losses and proceeds."]}]
]);
